/* Card set: US Navy (generated from the approved roster-final.csv by the Navy build, schema per tools/csv-to-set.js).
   (us-navy.js exceeds the comfortable push size, so the remaining cards live in
   us-navy-additions.js, which must stay directly after 'us-navy.js' in sets/manifest.js.) */
CardSets.register({"id":"us-navy","name":"US Navy","code":"NAVY","description":"420 cards of American sea power — flattops and battleships, cruisers, destroyers and submarines, amphibious and auxiliary workhorses, and the sailing frigates and ironclads that started it all.","theme":{"primary":"#1b3a5c","secondary":"#c9a227","artBackground":"#eef2f5","artFit":"cover"},"pack":{"name":"US Navy Pack","emblem":"⚓","skin":"us-navy"},"cards":[{"name":"USS Enterprise (CV-6)","rarity":"chase","id":"uss-enterprise-cv-6","subtitle":"Aircraft Carrier","details":"Yorktown-class carrier commissioned in 1938. The most decorated US warship of World War II, she earned 20 battle stars, from Pearl Harbor to Okinawa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Enterprise_%28CV-6%29_in_Puget_Sound%2C_September_1945.jpg?width=1024"},{"name":"USS Constitution","rarity":"chase","id":"uss-constitution-1797","subtitle":"Sailing Frigate","details":"Launched in 1797, 'Old Ironsides' won fame in the War of 1812 by defeating HMS Guerriere and HMS Java; she remains in commission in Boston.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Constitution%20fires%20a%2017-gun%20salute.jpg?width=1024"},{"name":"USS Missouri (BB-63)","rarity":"chase","id":"uss-missouri-bb-63","subtitle":"Battleship","details":"Iowa-class battleship commissioned in 1944; Japan's formal surrender ending World War II was signed on her deck in Tokyo Bay in September 1945.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Missouri_post_refit.JPG?width=1024"},{"name":"USS Arizona (BB-39)","rarity":"chase","id":"uss-arizona-bb-39","subtitle":"Battleship","details":"Pennsylvania-class battleship commissioned in 1916; sunk at Pearl Harbor on 7 December 1941, her wreck is a memorial to the 1,177 crewmen lost.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Arizona_%28BB39%29_Port_Bow%2C_Underway_-_NARA_-_5900075_-_1930.jpg?width=1024"},{"name":"USS Nautilus (SSN-571)","rarity":"chase","id":"uss-nautilus-ssn-571","subtitle":"Attack Submarine","details":"Commissioned in 1954, Nautilus was the world's first nuclear-powered submarine, famously signaling 'Underway on nuclear power' in January 1955.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Nautilus_SSN-571_-underway.jpg?width=1024"},{"name":"USS Iowa (BB-61)","rarity":"chase","id":"uss-iowa-bb-61","subtitle":"Battleship","details":"Lead ship of the fast Iowa class, commissioned in 1943; she carried President Franklin D. Roosevelt across the Atlantic to the Tehran Conference.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BB61_USS_Iowa_BB61_broadside_USN.jpg?width=1024"},{"name":"USS Hornet (CV-8)","rarity":"chase","id":"uss-hornet-cv-8","subtitle":"Aircraft Carrier","details":"Yorktown-class carrier commissioned in 1941 that launched Doolittle's Tokyo raiders in April 1942; lost at the Santa Cruz Islands battle that October.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aft_view_of_USS_Hornet_%28CV-8%29%2C_circa_in_late_1941_%28NH_81313%29.jpg?width=1024"},{"name":"USS Texas (BB-35)","rarity":"chase","id":"uss-texas-bb-35","subtitle":"Battleship","details":"New York-class dreadnought commissioned in 1914; the last surviving dreadnought-era battleship, she fought in both world wars and is a museum ship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Texas-2.jpg?width=1024"},{"name":"USS George Washington (SSBN-598)","rarity":"chase","id":"uss-george-washington-ssbn-598","subtitle":"Ballistic Missile Submarine","details":"Commissioned in 1959, George Washington was the first ballistic missile submarine, launching the first Polaris missile from underwater in 1960.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_George_Washington_%28SSBN-598%29_underway_at_sea%2C_circa_in_the_1970s.jpg?width=1024"},{"name":"USS Nimitz (CVN-68)","rarity":"chase","id":"uss-nimitz-cvn-68","subtitle":"Aircraft Carrier","details":"Lead ship of the Nimitz-class nuclear supercarriers, commissioned in 1975 and named for Fleet Admiral Chester W. Nimitz, Pacific commander of World War II.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Nimitz_%28CVN-68%29.jpg?width=1024"},{"name":"USS Lexington (CV-2)","rarity":"legendary","id":"uss-lexington-cv-2","subtitle":"Aircraft Carrier","details":"Converted from a battlecruiser and commissioned in 1927, 'Lady Lex' pioneered carrier aviation before her loss at the Coral Sea in May 1942.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Lexington_%28CV-2%29_leaving_San_Diego_on_14_October_1941_%2880-G-416362%29.jpg?width=1024"},{"name":"USS Yorktown (CV-5)","rarity":"legendary","id":"uss-yorktown-cv-5","subtitle":"Aircraft Carrier","details":"Lead ship of her class, commissioned in 1937. Her aircraft fought at the Coral Sea and Midway, where she was lost in June 1942 after a gallant fight.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Yorktown_%28CV-5%29_Jul1937.jpg?width=1024"},{"name":"USS Midway (CV-41)","rarity":"legendary","id":"uss-midway-cv-41","subtitle":"Aircraft Carrier","details":"Commissioned in September 1945, days after World War II ended, she served 47 years through Korea, Vietnam and Desert Storm; now a San Diego museum ship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Midway_%28CVB-41%29_steaming_off_the_Firth_of_Clyde_in_September_1952.jpg?width=1024"},{"name":"USS Enterprise (CVN-65)","rarity":"legendary","id":"uss-enterprise-cvn-65","subtitle":"Aircraft Carrier","details":"The world's first nuclear-powered aircraft carrier, commissioned in 1961; her eight reactors gave her unmatched endurance across a 51-year career.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Enterprise_%28CVN-65%29_underway_in_the_Atlantic_Ocean_on_14_June_2004_%28040614-N-0119G-020%29.jpg?width=1024"},{"name":"USS Saratoga (CV-3)","rarity":"legendary","id":"uss-saratoga-cv-3","subtitle":"Aircraft Carrier","details":"Commissioned in 1927 after conversion from a battlecruiser, she fought through World War II before her final duty in the 1946 Bikini atomic tests.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Saratoga_%28CV-3%29_underway%2C_circa_in_1942_%2880-G-K-459%29.jpg?width=1024"},{"name":"USS Essex (CV-9)","rarity":"legendary","id":"uss-essex-cv-9","subtitle":"Aircraft Carrier","details":"Lead ship of the 24-carrier Essex class, commissioned on the last day of 1942; her air groups struck across the Pacific in the war's final campaigns.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Essex_CVS-9_June_1967.jpg?width=1024"},{"name":"USS Gerald R. Ford (CVN-78)","rarity":"legendary","id":"uss-gerald-r-ford-cvn-78","subtitle":"Aircraft Carrier","details":"Lead ship of the Ford class, commissioned in 2017 with electromagnetic aircraft catapults, advanced arresting gear and a redesigned island.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Gerald_R._Ford_%28CVN-78%29_underway_in_the_Atlantic_Ocean_on_9_October_2022_%28221009-N-TL968-1248%29.JPG?width=1024"},{"name":"USS North Carolina (BB-55)","rarity":"legendary","id":"uss-north-carolina-bb-55","subtitle":"Battleship","details":"Lead of the first new US battleship class in two decades, commissioned in 1941; she earned 15 battle stars in Pacific service in World War II.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_North_Carolina_NYNY_11306-6-46.jpg?width=1024"},{"name":"USS New Jersey (BB-62)","rarity":"legendary","id":"uss-new-jersey-bb-62","subtitle":"Battleship","details":"Iowa-class battleship commissioned in 1943; the most decorated battleship in US Navy history, with 19 battle stars across three wars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/New_Jersey_Sails.jpg?width=1024"},{"name":"USS Wisconsin (BB-64)","rarity":"legendary","id":"uss-wisconsin-bb-64","subtitle":"Battleship","details":"Iowa-class battleship commissioned in 1944; she served in World War II and Korea, and fired Tomahawk missiles during the 1991 Gulf War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Wisconsin_%28BB-64%29_underway_at_sea%2C_circa_1988-1991_%28NH_97206-KN%29.jpg?width=1024"},{"name":"USS Oklahoma (BB-37)","rarity":"legendary","id":"uss-oklahoma-bb-37","subtitle":"Battleship","details":"Nevada-class battleship commissioned in 1916; capsized at Pearl Harbor on 7 December 1941 with the loss of 429 of her crew.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Oklahoma_BB-37.jpg?width=1024"},{"name":"USS West Virginia (BB-48)","rarity":"legendary","id":"uss-west-virginia-bb-48","subtitle":"Battleship","details":"Colorado-class battleship commissioned in 1923; sunk at Pearl Harbor in 1941, she was raised, rebuilt and returned to fight across the Pacific.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_West_Virginia_BB-48.jpg?width=1024"},{"name":"USS Washington (BB-56)","rarity":"legendary","id":"uss-washington-bb-56","subtitle":"Battleship","details":"North Carolina-class battleship commissioned in 1941; she sank the Japanese battleship Kirishima in a night action off Guadalcanal in 1942.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Washington_%28BB-56%29_in_Puget_Sound%2C_10_September_1945.jpg?width=1024"},{"name":"USS Indianapolis (CA-35)","rarity":"legendary","id":"uss-indianapolis-ca-35","subtitle":"Heavy Cruiser","details":"Portland-class heavy cruiser commissioned in 1932. She delivered atomic bomb components to Tinian in July 1945 and was torpedoed days later.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Indianapolis_%28CA-35%29_underway_at_sea_on_27_September_1939_%2880-G-425615%29.jpg?width=1024"},{"name":"USS Juneau (CL-52)","rarity":"legendary","id":"uss-juneau-cl-52","subtitle":"Light Cruiser","details":"Atlanta-class light cruiser commissioned in February 1942. She was lost at Guadalcanal that November; the five Sullivan brothers served aboard her.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Juneau_%28CL-52%29_-_19-N-28143.jpg?width=1024"},{"name":"USS San Francisco (CA-38)","rarity":"legendary","id":"uss-san-francisco-ca-38","subtitle":"Heavy Cruiser","details":"New Orleans-class heavy cruiser commissioned in 1934. She fought through the Naval Battle of Guadalcanal and earned 17 battle stars in the Pacific war.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_San_Francisco_%28CA-38%29_off_the_Mare_Island_Naval_Shipyard_on_13_October_1944_%2819-N-73588%29.jpg?width=1024"},{"name":"USS Johnston (DD-557)","rarity":"legendary","id":"uss-johnston-dd-557","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; in the Battle off Samar she charged a vastly larger Japanese force and was lost with 186 crew.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Johnston_%28DD-557%29_underway_on_27_October_1943_%28NH_63495%29.jpg?width=1024"},{"name":"USS Laffey (DD-724)","rarity":"legendary","id":"uss-laffey-dd-724","subtitle":"Destroyer","details":"Allen M. Sumner-class destroyer commissioned in 1944; off Okinawa in 1945 she survived hits by six kamikazes and four bombs and stayed afloat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Laffey_%28DD-724%29_underway_in_the_later_1940s_or_early_1950s_%28NH_107015%29.jpg?width=1024"},{"name":"USS Samuel B. Roberts (DE-413)","rarity":"legendary","id":"uss-samuel-b-roberts-de-413","subtitle":"Destroyer Escort","details":"John C. Butler-class destroyer escort commissioned in 1944; lost at the Battle off Samar after fighting cruisers many times her size.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Samuel_B._Roberts_%28DE-413%29_underway_in_October_1944_%28NH_96011%29.jpg?width=1024"},{"name":"USS Arleigh Burke (DDG-51)","rarity":"legendary","id":"uss-arleigh-burke-ddg-51","subtitle":"Guided Missile Destroyer","details":"Lead ship of her class, commissioned in 1991; her Aegis destroyers became the backbone class of the fleet, with over 70 ships built or planned.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Arleigh%20Burke%20%28DDG-51%29%20underway%20during%20sea%20trials%20in%201991.jpg?width=800"},{"name":"USS Ohio (SSBN-726)","rarity":"legendary","id":"uss-ohio-ssbn-726","subtitle":"Ballistic Missile Submarine","details":"Lead ship of her class, commissioned in 1981, Ohio was the largest submarine built for the U.S. Navy and the first of the Trident boomers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US_Navy_061029-N-1683M-002_Ohio-class_ballistic-missile_submarine_USS_Ohio_%28SSGN_726%29_cruises_toward_homeport_in_the_Hood_Canal_portion_of_the_Puget_Sound.jpg?width=1024"},{"name":"USS Tang (SS-306)","rarity":"legendary","id":"uss-tang-ss-306","subtitle":"Submarine","details":"Commissioned in 1943, Balao-class Tang sank more Japanese tonnage than any other U.S. submarine before being lost to her own torpedo in 1944.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Tang_%28SS-306%29_off_the_Mare_Island_Naval_Shipyard%2C_California_%28USA%29%2C_2_December_1943_%28NH_42273%29.jpg?width=1024"},{"name":"USS Wahoo (SS-238)","rarity":"legendary","id":"uss-wahoo-ss-238","subtitle":"Submarine","details":"Gato-class Wahoo, commissioned in 1942, became a Pacific legend under Dudley 'Mush' Morton before being lost with all hands in October 1943.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Wahoo_%28SS-238%29_off_the_Mare_Island_Naval_Shipyard%2C_California_%28USA%29%2C_on_14_July_1943_%2819-N-48937%29.jpg?width=1024"},{"name":"USS Barb (SS-220)","rarity":"legendary","id":"uss-barb-ss-220","subtitle":"Submarine","details":"Commissioned in 1942, Gato-class Barb won fame under Eugene Fluckey, sinking a carrier and landing the only U.S. ground raid on Japan's home islands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Barb_%28SS-220%29_underway_in_May_1945.jpg?width=1024"},{"name":"USS Triton (SSN-586)","rarity":"legendary","id":"uss-triton-ssn-586","subtitle":"Attack Submarine","details":"Commissioned in 1959, the giant radar-picket Triton made the first submerged circumnavigation of the Earth in 1960, following Magellan's route.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Triton_SSRN586_0858601.jpg?width=1024"},{"name":"USS Blue Ridge (LCC-19)","rarity":"legendary","id":"uss-blue-ridge-lcc-19","subtitle":"Command Ship","details":"Purpose-built as a fleet flagship and commissioned in 1970, Blue Ridge bristled with computers and communications gear for commanding fleets at sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blue_Ridge_2012.jpg?width=1024"},{"name":"USS Iwo Jima (LHD-7)","rarity":"legendary","id":"uss-iwo-jima-lhd-7","subtitle":"Amphibious Assault Ship","details":"Commissioned in 2001 as the seventh Wasp-class big deck, Iwo Jima carries Marines, helicopters and landing craft, honoring the 1945 island battle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US_Navy_080906-N-1082Z-029_The_multi-purpose_amphibious_assault_ship_USS_Iwo_Jima_%28LHD_7%29_transits_the_Atlantic_Ocean.jpg?width=1024"},{"name":"USS Monitor","rarity":"legendary","id":"uss-monitor-1862","subtitle":"Ironclad","details":"Launched in 1862, the ironclad Monitor fought CSS Virginia at Hampton Roads in the first battle between ironclad warships, changing naval warfare.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Monitor%20at%20sea.jpg?width=1024"},{"name":"USS Hartford","rarity":"legendary","id":"uss-hartford-1858","subtitle":"Steam Sloop","details":"Launched in 1858, Hartford was Farragut's flagship at Mobile Bay in 1864, remembered for the cry 'Damn the torpedoes, full speed ahead.'","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Hartford%20%281858%29.jpg?width=1024"},{"name":"USS Niagara (1813)","rarity":"legendary","id":"uss-niagara-1813","subtitle":"Sailing Brig","details":"Launched in 1813, Niagara was Perry's relief flagship at Lake Erie; when Lawrence was shattered, Perry rowed to Niagara and won the battle from her deck.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brig%20Niagara%20full%20sail.jpg?width=1024"},{"name":"USS Intrepid (CV-11)","rarity":"epic","id":"uss-intrepid-cv-11","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in 1943 that survived torpedo and kamikaze strikes, served in Vietnam, and is now a sea, air and space museum in New York.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Intrepid_%28CVS-11%29_underway_in_the_South_China_Sea_on_17_October_1968_%28NNMA.1996.488.244.058%29.jpg?width=1024"},{"name":"USS Franklin (CV-13)","rarity":"epic","id":"uss-franklin-cv-13","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in 1944 that survived the war's devastating carrier bombing off Japan in March 1945 and steamed home on her own power.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Franklin_%28CV-13%29_in_the_Elizabeth_River%2C_off_Norfolk%2C_Virginia_%28USA%29%2C_21_February_1944_%2880-G-224596%29.jpg?width=1024"},{"name":"USS Bunker Hill (CV-17)","rarity":"epic","id":"uss-bunker-hill-cv-17","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in 1943. Hit by two kamikazes off Okinawa in May 1945, she survived grievous losses and returned home for repairs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Bunker_Hill_%28CV-17%29_at_sea_in_1945_%28NH_42373%29.jpg?width=1024"},{"name":"USS Coral Sea (CV-43)","rarity":"epic","id":"uss-coral-sea-cv-43","subtitle":"Aircraft Carrier","details":"Midway-class carrier commissioned in 1947 and named for the first carrier-versus-carrier battle in history; she served through Vietnam until 1990.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Coral_Sea_%28CV-43%29_underway_at_sea_on_1_March_1989_%28NH_97651-KN%29.jpg?width=1024"},{"name":"USS Forrestal (CV-59)","rarity":"epic","id":"uss-forrestal-cv-59","subtitle":"Aircraft Carrier","details":"The first American supercarrier, commissioned in 1955 with an angled flight deck. A 1967 deck fire off Vietnam took 134 of her crew.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Forrestal_%28CVA-59%29_underway_at_sea_on_31_May_1962_%28KN-4507%29.jpg?width=1024"},{"name":"USS Kitty Hawk (CV-63)","rarity":"epic","id":"uss-kitty-hawk-cv-63","subtitle":"Aircraft Carrier","details":"Last of the Kitty Hawk-class supercarriers, commissioned in 1961; she served 48 years, from Vietnam to the wars after 2001, retiring in 2009.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US_Navy_050517-N-0120R-127_The_conventionally_powered_aircraft_carrier_USS_Kitty_Hawk_%28CV_63%29_sails_past_a_small_group_of_Japanese_fishing_vessels_and_heads_toward_Sagami_Bay.jpg?width=1024"},{"name":"USS John F. Kennedy (CV-67)","rarity":"epic","id":"uss-john-f-kennedy-cv-67","subtitle":"Aircraft Carrier","details":"Conventionally powered supercarrier commissioned in 1968 and named for the fallen president; the last oil-fired big-deck carrier built for the US Navy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_John_F._Kennedy_%28CV-67%29_departs_Naval_Station_Mayport_on_11_November_2003.jpg?width=1024"},{"name":"USS Theodore Roosevelt (CVN-71)","rarity":"epic","id":"uss-theodore-roosevelt-cvn-71","subtitle":"Aircraft Carrier","details":"Nimitz-class nuclear carrier commissioned in 1986, nicknamed 'the Big Stick' after President Theodore Roosevelt's famous foreign-policy maxim.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/200125-N-LH674-1073_USS_Theodore_Roosevelt_%28CVN-71%29.jpg?width=1024"},{"name":"USS Wasp (CV-7)","rarity":"epic","id":"uss-wasp-cv-7","subtitle":"Aircraft Carrier","details":"Sole ship of her class, commissioned in 1940 and built small under treaty limits; lost to a submarine in September 1942 during the Guadalcanal campaign.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Wasp_%28CV-7%29_entering_Hampton_Roads_on_26_May_1942.jpg?width=1024"},{"name":"USS Pennsylvania (BB-38)","rarity":"epic","id":"uss-pennsylvania-bb-38","subtitle":"Battleship","details":"Lead ship of her class, commissioned in 1916; flagship of the US Fleet in the 1930s, she survived Pearl Harbor and fought through the Pacific.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Pennsy_BB-38_1934.jpg?width=1024"},{"name":"USS Nevada (BB-36)","rarity":"epic","id":"uss-nevada-bb-36","subtitle":"Battleship","details":"Commissioned in 1916, the first oil-fired US battleship; the only battleship to get underway at Pearl Harbor, she later bombarded Normandy and Iwo Jima.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Uss_nevada.jpg?width=1024"},{"name":"USS California (BB-44)","rarity":"epic","id":"uss-california-bb-44","subtitle":"Battleship","details":"Tennessee-class battleship commissioned in 1921; sunk in shallow water at Pearl Harbor, she was raised and rebuilt to fight at Leyte and Okinawa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_California_%28BB-44%29_-_NH_61483.jpg?width=1024"},{"name":"USS Massachusetts (BB-59)","rarity":"epic","id":"uss-massachusetts-bb-59","subtitle":"Battleship","details":"South Dakota-class battleship commissioned in 1942; she fought at Casablanca and across the Pacific, and is preserved at Fall River, Massachusetts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Massachusetts_%28BB-59%29_underway_c1944.jpg?width=1024"},{"name":"USS South Dakota (BB-57)","rarity":"epic","id":"uss-south-dakota-bb-57","subtitle":"Battleship","details":"Lead ship of her class, commissioned in 1942; she fought at Santa Cruz and the Philippine Sea and took heavy damage in the Guadalcanal night battle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_South_Dakota_%28BB-57%29_off_the_Norfolk_Naval_Shipyard_on_20_August_1943_%28NH_97264%29.jpg?width=1024"},{"name":"USS New York (BB-34)","rarity":"epic","id":"uss-new-york-bb-34","subtitle":"Battleship","details":"Lead ship of the first US class armed with 14-inch guns, commissioned in 1914; she served in both world wars and survived two atomic bomb tests in 1946.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_New_York_%28BB-34%29_underway_at_high_speed_on_29_May_1915_%2819-N-13046%29.jpg?width=1024"},{"name":"USS Arkansas (BB-33)","rarity":"epic","id":"uss-arkansas-bb-33","subtitle":"Battleship","details":"Wyoming-class dreadnought commissioned in 1912; the oldest US battleship in service in World War II, she bombarded the Normandy beaches on D-Day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Arkansas_%28BB-33%29_1918.jpg?width=1024"},{"name":"USS Atlanta (CL-51)","rarity":"epic","id":"uss-atlanta-cl-51","subtitle":"Light Cruiser","details":"Lead ship of her class, commissioned on Christmas Eve 1941. She was lost in the Naval Battle of Guadalcanal in November 1942.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Atlanta_%28CL-51%29_steaming_at_high_speed%2C_circa_in_November_1941_%28NH_57455%29.jpg?width=1024"},{"name":"USS Olympia (C-6)","rarity":"epic","id":"uss-olympia-c-6","subtitle":"Protected Cruiser","details":"Protected cruiser commissioned in 1895 and Commodore Dewey's flagship at Manila Bay in 1898. She survives as a museum ship in Philadelphia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Olympia%3Bc0605.jpg?width=1024"},{"name":"USS Alaska (CB-1)","rarity":"epic","id":"uss-alaska-cb-1","subtitle":"Large Cruiser","details":"Lead Alaska-class large cruiser, commissioned in June 1944. She screened the fast carrier task forces and bombarded Okinawa and the Japanese home islands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Alaska_%28CB-1%29_off_the_Philadelphia_Navy_Yard_on_30_July_1944.jpg?width=1024"},{"name":"USS Long Beach (CGN-9)","rarity":"epic","id":"uss-long-beach-cgn-9","subtitle":"Guided Missile Cruiser","details":"Commissioned in 1961, Long Beach was the world's first nuclear-powered surface warship and the first cruiser built with guided missiles from the keel up.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Long_Beach_%28CGN-9%29_underway_off_Oahu_on_9_May_1973.jpg?width=1024"},{"name":"USS Quincy (CA-39)","rarity":"epic","id":"uss-quincy-ca-39","subtitle":"Heavy Cruiser","details":"New Orleans-class heavy cruiser commissioned in 1936. She was lost at the Battle of Savo Island in August 1942 while guarding the Guadalcanal transports.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Quincy_%28CA-39%29_in_New_York_harbour_on_23_May_1942_%2819-N-30732%29.jpg?width=1024"},{"name":"USS Helena (CL-50)","rarity":"epic","id":"uss-helena-cl-50","subtitle":"Light Cruiser","details":"St. Louis-class light cruiser commissioned in 1939. She survived the Pearl Harbor attack but was sunk by torpedoes at Kula Gulf in July 1943.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Helena_NH_95812.jpg?width=1024"},{"name":"USS Fletcher (DD-445)","rarity":"epic","id":"uss-fletcher-dd-445","subtitle":"Destroyer","details":"Lead ship of the 175-strong Fletcher class, commissioned in 1942; the class became the workhorse destroyer design of the Second World War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Fletcher_%28DD-445%29_underway_at_sea%2C_circa_the_1960s_%28NH_68912%29.jpg?width=1024"},{"name":"USS The Sullivans (DD-537)","rarity":"epic","id":"uss-the-sullivans-dd-537","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943 and named for the five Sullivan brothers lost on USS Juneau; now a museum ship in Buffalo.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_The_Sullivans_%28DD-537%29_underway_at_sea_on_29_October_1962_%28USN_1063617%29.jpg?width=1024"},{"name":"USS O'Bannon (DD-450)","rarity":"epic","id":"uss-obannon-dd-450","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; famous for the 1943 potato incident and among the most decorated US destroyers of the war.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20O%27Bannon%20%28DD-450%29%20in%201942.jpg?width=1024"},{"name":"USS Hoel (DD-533)","rarity":"epic","id":"uss-hoel-dd-533","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; lost at the Battle off Samar, where her torpedo attacks helped turn back a Japanese battleship force.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Hoel_%28DD-533%29_off_San_Francisco%2C_3_August_1943.jpg?width=1024"},{"name":"USS Cole (DDG-67)","rarity":"epic","id":"uss-cole-ddg-67","subtitle":"Guided Missile Destroyer","details":"Arleigh Burke-class destroyer commissioned in 1996; in October 2000 a bombing in Aden harbour killed 17 of her sailors. She later returned to service.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Cole_%28DDG-67%29_turn.jpg?width=1024"},{"name":"USS Zumwalt (DDG-1000)","rarity":"epic","id":"uss-zumwalt-ddg-1000","subtitle":"Guided Missile Destroyer","details":"Lead ship of the Zumwalt class, commissioned in 2016; her angular stealth hull and electric drive made her the Navy's most futuristic destroyer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Zumwalt%20%28DDG%201000%29%20underway%20for%20the%20first%20time%20151207-N-ZZ999-001.jpg?width=1024"},{"name":"USS Ward (DD-139)","rarity":"epic","id":"uss-ward-dd-139","subtitle":"Destroyer","details":"Wickes-class destroyer commissioned in 1918; on 7 December 1941 she sank a Japanese midget submarine at Pearl Harbor, firing the day's first US shots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Ward%20%28DD-139%29%20on%2026%20February%201919%20%28NH%2063240%29.jpg?width=1024"},{"name":"USS Reuben James (DD-245)","rarity":"epic","id":"uss-reuben-james-dd-245","subtitle":"Destroyer","details":"Clemson-class destroyer commissioned in 1920; torpedoed by U-552 on 31 October 1941, she was the first US Navy ship lost in the Second World War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Reuben_James_%28DD-245%29_on_29_April_1939.jpg?width=1024"},{"name":"USS England (DE-635)","rarity":"epic","id":"uss-england-de-635","subtitle":"Destroyer Escort","details":"Buckley-class destroyer escort commissioned in 1943; in May 1944 she sank six Japanese submarines in twelve days, an unmatched antisubmarine record.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_England_%28DE-635%29_underway_off_San_Francisco_on_9_February_1944_%2819-N-60938%29.jpg?width=1024"},{"name":"USS Stark (FFG-31)","rarity":"epic","id":"uss-stark-ffg-31","subtitle":"Guided Missile Frigate","details":"Oliver Hazard Perry-class frigate commissioned in 1982; struck by two Exocet missiles in the Persian Gulf in 1987, she survived and was repaired.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Stark%20%28FFG-31%29%20underway%20in%20the%20Pacific%20Ocean%20on%2013%20July%201982.jpeg?width=1024"},{"name":"USS Thresher (SSN-593)","rarity":"epic","id":"uss-thresher-ssn-593","subtitle":"Attack Submarine","details":"Commissioned in 1961, Thresher was lost with all 129 aboard during deep-diving trials in April 1963, a tragedy that created the SUBSAFE program.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Thresher%3B0859306.jpg?width=1024"},{"name":"USS Scorpion (SSN-589)","rarity":"epic","id":"uss-scorpion-ssn-589","subtitle":"Attack Submarine","details":"Skipjack-class Scorpion, commissioned in 1960, was lost with all 99 aboard southwest of the Azores in May 1968; her wreck was found that October.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/NH_97214_USS_Scorpion_%28SSN-589%29_%28cropped%29.tif?width=1024"},{"name":"USS Archerfish (SS-311)","rarity":"epic","id":"uss-archerfish-ss-311","subtitle":"Submarine","details":"Commissioned in 1943, Balao-class Archerfish sank the Japanese carrier Shinano in November 1944, the largest warship ever sunk by a submarine.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Archerfish%3B0831110.jpg?width=1024"},{"name":"USS Batfish (SS-310)","rarity":"epic","id":"uss-batfish-ss-310","subtitle":"Submarine","details":"Commissioned in 1943, Batfish sank three Japanese submarines in just 76 hours in February 1945, a feat unmatched by any other U.S. submarine.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_BATFISH_2013.JPG?width=1024"},{"name":"USS Flasher (SS-249)","rarity":"epic","id":"uss-flasher-ss-249","subtitle":"Submarine","details":"Commissioned in 1943, Flasher was credited with the most enemy tonnage sunk by any U.S. submarine under postwar accounting, over 100,000 tons.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Flasher%3B0824904.jpg?width=1024"},{"name":"USS Harder (SS-257)","rarity":"epic","id":"uss-harder-ss-257","subtitle":"Submarine","details":"Commissioned in 1942, Harder earned the nickname 'Hit 'em HARDER' and five battle stars before being lost with all hands off Luzon in August 1944.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Harder%3B0825713.jpg?width=1024"},{"name":"USS Seawolf (SSN-21)","rarity":"epic","id":"uss-seawolf-ssn-21","subtitle":"Attack Submarine","details":"Commissioned in 1997, Seawolf was the lead ship of a three-boat class built for Cold War missions and later based in the Pacific Northwest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Seawolf_%28SSN-21%29_%2821274044216%29.jpg?width=1024"},{"name":"USS Wasp (LHD-1)","rarity":"epic","id":"uss-wasp-lhd-1","subtitle":"Amphibious Assault Ship","details":"Lead ship of her class, commissioned in 1989, Wasp was the first amphibious assault ship designed from the keel up to operate LCAC hovercraft.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Wasp_%28LHD-1%29_Osprey_2.jpg?width=1024"},{"name":"USS America (LHA-6)","rarity":"epic","id":"uss-america-lha-6","subtitle":"Amphibious Assault Ship","details":"Commissioned in 2014, America was the first LHA built without a well deck, trading it for extra aviation space to support F-35B jets and Ospreys.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_America_%28LHA-6%29_F-35B_loaded.jpg?width=1024"},{"name":"USS Mount Whitney (LCC-20)","rarity":"epic","id":"uss-mount-whitney-lcc-20","subtitle":"Command Ship","details":"Commissioned in 1971, Mount Whitney is a purpose-built amphibious command ship, long serving as a flagship for fleets in European waters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Mount%20Whitney%20%28LCC-20%29%20underway%20in%20the%20Med%20in%202013.JPG?width=1024"},{"name":"USS Kearsarge","rarity":"epic","id":"uss-kearsarge-1861","subtitle":"Steam Sloop","details":"Launched in 1861, the steam sloop Kearsarge hunted Confederate raiders for a year before sinking CSS Alabama off Cherbourg, France, in June 1864.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Kearsarge%20%281861%29.jpg?width=1024"},{"name":"USS Constellation","rarity":"epic","id":"uss-constellation-1797","subtitle":"Sailing Frigate","details":"Launched in 1797, Constellation won the young Navy's first victories, capturing French frigate L'Insurgente and defeating La Vengeance in the Quasi-War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USSConstellationCropped.png?width=400"},{"name":"USS Essex","rarity":"epic","id":"uss-essex-1799","subtitle":"Sailing Frigate","details":"Launched in 1799, David Porter's frigate Essex raided British whaling ships across the Pacific in the War of 1812 before her capture at Valparaiso.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Frigate-essex-1799.jpg?width=1024"},{"name":"USS New Ironsides","rarity":"epic","id":"uss-new-ironsides-1862","subtitle":"Ironclad","details":"Launched in 1862, the broadside ironclad New Ironsides was the most powerful warship commissioned by the United States Navy during the Civil War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/New%20ironsides%20sails.jpg?width=1024"},{"name":"USS Ranger (CV-4)","rarity":"rare","id":"uss-ranger-cv-4","subtitle":"Aircraft Carrier","details":"The first US ship designed and built from the keel up as an aircraft carrier, commissioned in 1934; she served mainly in the Atlantic in World War II.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Ranger_%28CV-4%29_underway_at_sea_during_the_later_1930s.jpg?width=1024"},{"name":"USS Yorktown (CV-10)","rarity":"rare","id":"uss-yorktown-cv-10","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in 1943 and named for her lost predecessor; she fought in World War II and Vietnam and is now a museum at Patriots Point.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Yorktown_%28CVS-10%29_underway_at_sea_on_10_March_1963.jpg?width=1024"},{"name":"USS Hornet (CV-12)","rarity":"rare","id":"uss-hornet-cv-12","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in 1943 that recovered the Apollo 11 and Apollo 12 astronauts after their Moon missions; now a museum in Alameda.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Hornet_%28CVS-12%29_underway_in_1969.jpg?width=1024"},{"name":"USS Lexington (CV-16)","rarity":"rare","id":"uss-lexington-cv-16","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in 1943, dubbed 'the Blue Ghost' after Tokyo Rose reported her sunk again and again; now a museum in Corpus Christi.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Lexington_%28CVA-16%29_underway_at_sea_on_16_August_1958.jpg?width=1024"},{"name":"USS Hancock (CV-19)","rarity":"rare","id":"uss-hancock-cv-19","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in 1944 that fought through the Philippines and Okinawa, then launched Vietnam-era strikes before retiring in 1976.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Hancock_%28CVA-19%29_off_Pearl_Harbor_1968.jpg?width=1024"},{"name":"USS Antietam (CV-36)","rarity":"rare","id":"uss-antietam-cv-36","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in January 1945, too late for World War II combat but a Korean War veteran; she later became the Navy's training carrier.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Antietam_%28CVS-36%29_operating_training_aircraft_on_19_April_1961_%28KN-4834%29.jpg?width=1024"},{"name":"USS Shangri-La (CV-38)","rarity":"rare","id":"uss-shangri-la-cv-38","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in 1944, jokingly named for the fictional land the Doolittle raiders were said to have flown from against Tokyo.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Shangri-La_%28CV-38%29_underway_in_the_Pacific_Ocean%2C_17_August_1946_%2880-G-278827%29.jpg?width=1024"},{"name":"USS Independence (CVL-22)","rarity":"rare","id":"uss-independence-cvl-22","subtitle":"Light Aircraft Carrier","details":"Lead ship of the Independence-class light carriers, converted from a cruiser hull and commissioned in 1943; she fought across the Pacific in World War II.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Independence_%28CVL-22%29_in_San_Francisco_Bay_on_15_July_1943_%2880-G-74436%29.jpg?width=1024"},{"name":"USS Princeton (CVL-23)","rarity":"rare","id":"uss-princeton-cvl-23","subtitle":"Light Aircraft Carrier","details":"Independence-class light carrier commissioned in 1943, lost at Leyte Gulf in October 1944 after one bomb ignited her fueled and armed aircraft.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Princeton_%28CVL-23%29_underway_in_Puget_Sound_on_3_January_1944_%28NH_95651%29.jpg?width=1024"},{"name":"USS Saratoga (CV-60)","rarity":"rare","id":"uss-saratoga-cv-60","subtitle":"Aircraft Carrier","details":"Forrestal-class supercarrier commissioned in 1956, third carrier to bear the name; she served through Vietnam and Desert Storm before retiring in 1994.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Saratoga_%28CV-60%29_underway_in_the_Adriatic_Sea_on_29_July_1992_%286480624%29.jpg?width=1024"},{"name":"USS Constellation (CV-64)","rarity":"rare","id":"uss-constellation-cv-64","subtitle":"Aircraft Carrier","details":"Kitty Hawk-class supercarrier commissioned in 1961, nicknamed 'Connie'; she served 41 years, from Vietnam through the 2003 invasion of Iraq.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Constellation_%28CV-64%29_off_Perth%2C_Australia%2C_on_29_April_2003.jpg?width=1024"},{"name":"USS Abraham Lincoln (CVN-72)","rarity":"rare","id":"uss-abraham-lincoln-cvn-72","subtitle":"Aircraft Carrier","details":"Nimitz-class nuclear carrier commissioned in 1989. In May 2003 she hosted the famous 'Mission Accomplished' address early in the Iraq War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Abraham_Lincoln_%28CVN-72%29_underway_in_the_Atlantic_Ocean_on_30_January_2019_%28190130-N-PW716-1312%29.JPG?width=1024"},{"name":"USS Tennessee (BB-43)","rarity":"rare","id":"uss-tennessee-bb-43","subtitle":"Battleship","details":"Lead ship of her class, commissioned in 1920; damaged at Pearl Harbor, she was rebuilt and bombarded Japanese positions from Saipan to Okinawa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Tennessee_BB43.jpg?width=1024"},{"name":"USS Colorado (BB-45)","rarity":"rare","id":"uss-colorado-bb-45","subtitle":"Battleship","details":"Lead ship of the 'Big Five' class armed with 16-inch guns, commissioned in 1923; she fought at Tarawa, Tinian, Leyte and Okinawa in World War II.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Colorado_%28BB-45%29_New_York_1932.jpg?width=1024"},{"name":"USS Maryland (BB-46)","rarity":"rare","id":"uss-maryland-bb-46","subtitle":"Battleship","details":"Colorado-class battleship commissioned in 1921; damaged at Pearl Harbor, she returned to service and fought at Tarawa, Saipan and Leyte Gulf.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Maryland_%28BB-46%29_underway_in_1935.jpg?width=1024"},{"name":"USS Indiana (BB-58)","rarity":"rare","id":"uss-indiana-bb-58","subtitle":"Battleship","details":"South Dakota-class battleship commissioned in 1942; she fought across the Pacific from Guadalcanal to Okinawa and supported the Iwo Jima landings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Indiana_%28BB-58%29_-_80-G-222923.jpg?width=1024"},{"name":"USS Alabama (BB-60)","rarity":"rare","id":"uss-alabama-bb-60","subtitle":"Battleship","details":"South Dakota-class battleship commissioned in 1942; she escorted Arctic convoys and fought across the Pacific, and is a museum ship in Mobile, Alabama.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Alabama_%28BB-60%29_in_Casco_Bay_c1942.jpg?width=1024"},{"name":"USS Wyoming (BB-32)","rarity":"rare","id":"uss-wyoming-bb-32","subtitle":"Battleship","details":"Lead ship of her class, commissioned in 1912; later converted to a gunnery training ship, she trained some 35,000 sailors during World War II.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Wyoming_BB-32_circa_1912-13.jpg?width=1024"},{"name":"USS Florida (BB-30)","rarity":"rare","id":"uss-florida-bb-30","subtitle":"Battleship","details":"Lead ship of her class, commissioned in 1911; among the first US dreadnoughts, she served with the Atlantic Fleet through the First World War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Florida_%28BB-30%29_-_NH_60568.jpg?width=1024"},{"name":"USS Utah (BB-31)","rarity":"rare","id":"uss-utah-bb-31","subtitle":"Battleship","details":"Florida-class dreadnought commissioned in 1911; later a target ship, she was sunk at Pearl Harbor in 1941 and her wreck remains there as a memorial.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USSutah2.jpg?width=1024"},{"name":"USS Oregon (BB-3)","rarity":"rare","id":"uss-oregon-bb-3","subtitle":"Battleship","details":"Indiana-class pre-dreadnought commissioned in 1896; she raced 14,000 nautical miles from San Francisco to Florida to fight in the Spanish-American War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Oregon_in_dry_dock%2C_1898.jpg?width=1024"},{"name":"USS Pensacola (CA-24)","rarity":"rare","id":"uss-pensacola-ca-24","subtitle":"Heavy Cruiser","details":"Lead ship of the Navy's first treaty heavy cruisers, commissioned in 1930. She screened carriers and fought from Guadalcanal to Iwo Jima and Okinawa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pensacola_CA-24_Louis_Claes.jpg?width=1024"},{"name":"USS Portland (CA-33)","rarity":"rare","id":"uss-portland-ca-33","subtitle":"Heavy Cruiser","details":"Portland-class heavy cruiser commissioned in 1933. She fought at Coral Sea, Midway and the Santa Cruz Islands, and at Surigao Strait.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Portland_%28CA-33%29_at_Pearl_Harbor_1942.jpg?width=1024"},{"name":"USS New Orleans (CA-32)","rarity":"rare","id":"uss-new-orleans-ca-32","subtitle":"Heavy Cruiser","details":"Lead New Orleans-class heavy cruiser, commissioned in 1934. Badly mauled at Tassafaronga, she was repaired and fought on to earn 17 battle stars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_New_Orleans_%28CA-32%29_underway_in_Puget_Sound_on_30_July_1943_%28NH_94847%29.jpg?width=1024"},{"name":"USS Astoria (CA-34)","rarity":"rare","id":"uss-astoria-ca-34","subtitle":"Heavy Cruiser","details":"New Orleans-class heavy cruiser commissioned in 1934. She fought at Coral Sea and Midway and was lost at Savo Island in August 1942.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Astoria_%28CA-34%29_operating_in_Hawaiian_waters_on_8_July_1942_%28NH_97682%29.jpg?width=1024"},{"name":"USS Vincennes (CA-44)","rarity":"rare","id":"uss-vincennes-ca-44","subtitle":"Heavy Cruiser","details":"New Orleans-class heavy cruiser commissioned in 1937, the second ship of the name. She was lost at the Battle of Savo Island in August 1942.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Vincennes_%28CA-44%29_in_Panama_Canal_1938.jpg?width=1024"},{"name":"USS Wichita (CA-45)","rarity":"rare","id":"uss-wichita-ca-45","subtitle":"Heavy Cruiser","details":"A unique heavy cruiser design commissioned in 1939, the last US treaty cruiser. She served in the Atlantic and Pacific and earned 13 battle stars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Wichita_CA-45.jpg?width=1024"},{"name":"USS Baltimore (CA-68)","rarity":"rare","id":"uss-baltimore-ca-68","subtitle":"Heavy Cruiser","details":"Lead Baltimore-class heavy cruiser, commissioned in April 1943. She supported the Makin, Kwajalein, Truk and Saipan operations of 1943 and 1944.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Baltimore_%28CA-68%29_off_the_Mare_Island_Naval_Shipyard_on_18_October_1944_%28NH_91462%29_%28cropped%29.jpg?width=1024"},{"name":"USS Boston (CA-69)","rarity":"rare","id":"uss-boston-ca-69","subtitle":"Heavy Cruiser","details":"Baltimore-class heavy cruiser commissioned in June 1943. She was converted after the war and recommissioned in 1955 as the missile cruiser CAG-1.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Boston.jpg?width=1024"},{"name":"USS Guam (CB-2)","rarity":"rare","id":"uss-guam-cb-2","subtitle":"Large Cruiser","details":"Alaska-class large cruiser commissioned in September 1944. She joined her sister Alaska screening the fast carriers off Okinawa and the China coast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Guam_%28CB-2%29_coming_out_of_a_turn%2C_circa_1944_%28NH_97131%29.jpg?width=1024"},{"name":"USS Nicholas (DD-449)","rarity":"rare","id":"uss-nicholas-dd-449","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; she earned 16 battle stars in the Second World War and served again off Korea and Vietnam.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Nicholas_%28DD-449%29_running_trials_in_May_1942_%28NH_49969%29.jpg?width=1024"},{"name":"USS Radford (DD-446)","rarity":"rare","id":"uss-radford-dd-446","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; she earned a Presidential Unit Citation in the Solomons and rescued 271 survivors of USS Helena.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Radford_%28DD-446%29_underway_in_1942.jpg?width=1024"},{"name":"USS Cassin Young (DD-793)","rarity":"rare","id":"uss-cassin-young-dd-793","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; hit by kamikazes off Okinawa, she is preserved as a museum ship in Boston beside USS Constitution.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Cassin%20Young%20%28DD-793%29%20underway%20on%2014%20January%201958%20%28NH%20107175%29.jpg?width=1024"},{"name":"USS Kidd (DD-661)","rarity":"rare","id":"uss-kidd-dd-661","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; her crew flew the Jolly Roger, and she is now a museum ship in Baton Rouge, still in wartime trim.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Kidd_%28DD-661%29_underway_c1951.jpeg?width=1024"},{"name":"USS Laffey (DD-459)","rarity":"rare","id":"uss-laffey-dd-459","subtitle":"Destroyer","details":"Benson-class destroyer commissioned in 1942; lost in the Naval Battle of Guadalcanal after a point-blank night duel with the battleship Hiei.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Laffey_%28DD-459%29_underway_in_the_South_Pacific_on_4_September_1942_%28NH_97864%29.jpg?width=1024"},{"name":"USS Aaron Ward (DD-483)","rarity":"rare","id":"uss-aaron-ward-dd-483","subtitle":"Destroyer","details":"Gleaves-class destroyer commissioned in 1942; mauled by Japanese aircraft off Guadalcanal, she sank under tow in April 1943 after a final bombing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Aaron_Ward_%28DD-483%29_underway_in_the_South_Pacific%2C_17_August_1942_%2880-G-12263%29.jpg?width=1024"},{"name":"USS Mahan (DD-364)","rarity":"rare","id":"uss-mahan-dd-364","subtitle":"Destroyer","details":"Lead ship of the Mahan class, commissioned in 1936; she fought across the Pacific before being lost to kamikaze attacks in December 1944.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USSMahanDD364.jpg?width=1024"},{"name":"USS Hammann (DD-412)","rarity":"rare","id":"uss-hammann-dd-412","subtitle":"Destroyer","details":"Sims-class destroyer commissioned in 1939; torpedoed by a Japanese submarine alongside USS Yorktown at Midway in June 1942 while aiding the carrier.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Hammann_DD-412_completed_1939.jpg?width=1024"},{"name":"USS Monssen (DD-436)","rarity":"rare","id":"uss-monssen-dd-436","subtitle":"Destroyer","details":"Gleaves-class destroyer commissioned in 1941; lost in the Naval Battle of Guadalcanal, where she was caught in a close-range night action.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Uss_Monssen_0543602.jpg?width=1024"},{"name":"USS Spruance (DD-963)","rarity":"rare","id":"uss-spruance-dd-963","subtitle":"Destroyer","details":"Lead ship of the Spruance class, commissioned in 1975; the 31 ships of her class introduced quiet, spacious hulls later reused by cruisers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A_port_bow_view_of_the_destroyer_USS_SPRUANCE_%28DDG-963%29_homeported_at_Naval_Station_Mayport%2C_FL%2C_operates_off_the_coast_of_Haiti.%28Exact_date_unknown%29_-_DPLA_-_2579ecbac86dfae78ac4144f8941b4ca.jpeg?width=1024"},{"name":"USS Donald Cook (DDG-75)","rarity":"rare","id":"uss-donald-cook-ddg-75","subtitle":"Guided Missile Destroyer","details":"Arleigh Burke-class destroyer commissioned in 1998; named for a Marine colonel and Medal of Honor recipient who died as a prisoner in Vietnam.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bow%20view%20of%20USS%20Donald%20Cook%20%28DDG-75%29%20in%20formation%20during%20Operation%20Iraqi%20Freedom%20030329-N-6141B-001.jpg?width=1024"},{"name":"USS John Paul Jones (DDG-53)","rarity":"rare","id":"uss-john-paul-jones-ddg-53","subtitle":"Guided Missile Destroyer","details":"Arleigh Burke-class destroyer commissioned in 1993; named for the Revolutionary War captain famous for the words 'I have not yet begun to fight.'","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_John_Paul_Jones.jpg?width=1024"},{"name":"USS Oliver Hazard Perry (FFG-7)","rarity":"rare","id":"uss-oliver-hazard-perry-ffg-7","subtitle":"Guided Missile Frigate","details":"Lead ship of her frigate class, commissioned in 1977; 71 ships of the design were built for the US and allied navies around the world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Oliver%20Hazard%20Perry%20%28FFG-7%29%20underway%20in%20late%201977.jpg?width=1024"},{"name":"USS Samuel B. Roberts (FFG-58)","rarity":"rare","id":"uss-samuel-b-roberts-ffg-58","subtitle":"Guided Missile Frigate","details":"Oliver Hazard Perry-class frigate commissioned in 1986; in April 1988 she struck a mine in the Persian Gulf, and her crew's damage control saved her.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US_Navy_070409-N-5459S-109_Oliver_Hazard_Perry-class_frigate_USS_Samuel_B._Roberts_%28FFG_58%29_navigates_in_the_Caribbean_Sea_during_an_exercise.jpg?width=1024"},{"name":"USS Bowfin (SS-287)","rarity":"rare","id":"uss-bowfin-ss-287","subtitle":"Submarine","details":"Launched on the first anniversary of Pearl Harbor in 1942, Balao-class Bowfin made nine patrols and is now a museum ship at Pearl Harbor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Bowfin_Submarine_Museum_%26_Park%2C_Pearl_Harbor%2C_Honolulu_%28503653%29_%2820588889142%29.jpg?width=1024"},{"name":"USS Drum (SS-228)","rarity":"rare","id":"uss-drum-ss-228","subtitle":"Submarine","details":"Commissioned in 1942, Gato-class Drum completed thirteen war patrols and later became a museum ship at Mobile, Alabama's Battleship Memorial Park.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Drum_SS-228_in_Mobile.jpg?width=1024"},{"name":"USS Silversides (SS-236)","rarity":"rare","id":"uss-silversides-ss-236","subtitle":"Submarine","details":"Commissioned in 1941 days after Pearl Harbor, Silversides made fourteen patrols and is preserved as a museum ship at Muskegon, Michigan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Silversides%3B0823622.jpg?width=1024"},{"name":"USS Cod (SS-224)","rarity":"rare","id":"uss-cod-ss-224","subtitle":"Submarine","details":"Commissioned in 1943, Cod rescued the crew of a Dutch submarine in 1945, the only international sub-to-sub rescue, and is a Cleveland museum.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Cod%3B0822430.jpg?width=1024"},{"name":"USS Growler (SS-215)","rarity":"rare","id":"uss-growler-ss-215","subtitle":"Submarine","details":"Commissioned in 1942, Growler rammed a Japanese gunboat while mortally wounded commander Howard Gilmore ordered 'Take her down,' saving his boat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Growler_%28SS-215%29_off_Groton%2C_Connecticut_%28USA%29%2C_on_21_February_1942_%2819-N-28445%29.jpg?width=1024"},{"name":"USS Trigger (SS-237)","rarity":"rare","id":"uss-trigger-ss-237","subtitle":"Submarine","details":"Commissioned in 1942, Trigger made twelve patrols and earned eleven battle stars before being lost with all hands in the East China Sea in 1945.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Trigger%3B0823701.jpg?width=1024"},{"name":"USS Skate (SSN-578)","rarity":"rare","id":"uss-skate-ssn-578","subtitle":"Attack Submarine","details":"Commissioned in 1957, Skate was the third nuclear submarine and in March 1959 became the first submarine ever to surface at the North Pole.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Skate_%28SSN-578%29%3B0857816.jpg?width=1024"},{"name":"USS Albacore (AGSS-569)","rarity":"rare","id":"uss-albacore-agss-569","subtitle":"Research Submarine","details":"Commissioned in 1953, experimental Albacore pioneered the modern teardrop hull form that shaped every U.S. submarine design that followed her.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Albacore_%28AGSS-569%29_underway_off_Newport%2C_Rhode_Island_%28USA%29%2C_11_March_1957_%2880-G-K-22262%29.jpg?width=1024"},{"name":"USS Virginia (SSN-774)","rarity":"rare","id":"uss-virginia-ssn-774","subtitle":"Attack Submarine","details":"Lead ship of her class, commissioned in 2004, Virginia brought modular construction and a photonics mast in place of a traditional periscope.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US_Navy_040730-N-1234E-002_PCU_Virginia_%28SSN_774%29_returns_to_the_General_Dynamics_Electric_Boat_shipyard.jpg?width=1024"},{"name":"USS Los Angeles (SSN-688)","rarity":"rare","id":"uss-los-angeles-ssn-688","subtitle":"Attack Submarine","details":"Lead ship commissioned in 1976, Los Angeles named a class of 62 attack submarines, the largest nuclear submarine class built for the U.S. Navy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Los_Angeles%3B0868802.jpg?width=1024"},{"name":"USS Lafayette (SSBN-616)","rarity":"rare","id":"uss-lafayette-ssbn-616","subtitle":"Ballistic Missile Submarine","details":"Lead ship commissioned in 1963, Lafayette named the largest class of ballistic missile submarines built for the U.S. Navy, with 31 boats in all.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Lafayette_SSBN-616.jpg?width=1024"},{"name":"USS Ethan Allen (SSBN-608)","rarity":"rare","id":"uss-ethan-allen-ssbn-608","subtitle":"Ballistic Missile Submarine","details":"Lead ship commissioned in 1961, Ethan Allen was the first submarine designed from the keel up as a ballistic missile submarine for the U.S. Navy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USSEthanAllenSSBN-608.jpg?width=1024"},{"name":"USS Tarawa (LHA-1)","rarity":"rare","id":"uss-tarawa-lha-1","subtitle":"Amphibious Assault Ship","details":"Lead ship of five general-purpose amphibious assault ships, commissioned in 1976, Tarawa combined helicopters, Harriers, landing craft and Marines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US_Navy_020628-N-3228G-002_USS_Tarawa_%28LHA_1%29.jpg?width=1024"},{"name":"USS Essex (LHD-2)","rarity":"rare","id":"uss-essex-lhd-2","subtitle":"Amphibious Assault Ship","details":"Commissioned in 1992, Essex is a Wasp-class big deck that spent decades forward-deployed to Japan, launching Marines and aircraft across the Pacific.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Essex_LHD_2.jpg?width=1024"},{"name":"USS Kearsarge (LHD-3)","rarity":"rare","id":"uss-kearsarge-lhd-3","subtitle":"Amphibious Assault Ship","details":"Commissioned in 1993, Kearsarge is a Wasp-class amphibious assault ship whose decks have launched everything from Harriers to relief helicopters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US_Navy_040620-N-1512S-218_The_amphibious_assault_ship_USS_Kearsarge_%28LHD_3%29_underway_while_transiting_the_Straits_of_Gibraltar_and_into_the_Mediterranean_Sea.jpg?width=1024"},{"name":"USS Boxer (LHD-4)","rarity":"rare","id":"uss-boxer-lhd-4","subtitle":"Amphibious Assault Ship","details":"Commissioned in 1995, Boxer is a Wasp-class big deck named for a 19th-century sailing brig, carrying Marines and aircraft on worldwide deployments.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US_Navy_110818-N-ZS026-035_The_USS_Boxer_steams_across_the_Indian_Ocean.jpg?width=1024"},{"name":"USS Bataan (LHD-5)","rarity":"rare","id":"uss-bataan-lhd-5","subtitle":"Amphibious Assault Ship","details":"Commissioned in 1997, Bataan was the first US warship built with berthing designed for women sailors, and honors the defenders of Bataan Peninsula.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Bataan_%28LHD-5%29%3B10080504.jpg?width=1024"},{"name":"USS Bonhomme Richard (LHD-6)","rarity":"rare","id":"uss-bonhomme-richard-lhd-6","subtitle":"Amphibious Assault Ship","details":"Commissioned in 1998, this Wasp-class big deck carried John Paul Jones's famous fighting name before a 2020 pier-side fire ended her service.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Bonhomme_Richard_transits_near_the_Royal_Australian_Navy_ship._%2835646532324%29.jpg?width=1024"},{"name":"USS United States","rarity":"rare","id":"uss-united-states-1797","subtitle":"Sailing Frigate","details":"Launched in 1797 and first of the six original frigates to launch, United States under Stephen Decatur captured HMS Macedonian in October 1812.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USSUnitedStates1797.jpg?width=1024"},{"name":"USS President","rarity":"rare","id":"uss-president-1800","subtitle":"Sailing Frigate","details":"Launched in 1800, President was among the fastest of the original six frigates; her 1811 clash with HMS Little Belt helped bring on the War of 1812.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20President%20partially%20down-rigged%20%28cropped%29.jpg?width=1024"},{"name":"USS Congress","rarity":"rare","id":"uss-congress-1799","subtitle":"Sailing Frigate","details":"Launched in 1799, Congress was one of the six original frigates of the U.S. Navy, cruising against French privateers in the Quasi-War with France.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Congress%20%28NH%2057005%29.jpg?width=1024"},{"name":"USS Chesapeake","rarity":"rare","id":"uss-chesapeake-1799","subtitle":"Sailing Frigate","details":"Launched in 1799, Chesapeake fought HMS Shannon off Boston in 1813; dying Captain Lawrence's plea, 'Don't give up the ship,' became a Navy rallying cry.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USSChesapeake.jpg?width=1024"},{"name":"USS Bonhomme Richard","rarity":"rare","id":"uss-bonhomme-richard-1779","subtitle":"Sailing Frigate","details":"John Paul Jones's converted merchantman defeated HMS Serapis in 1779; asked to surrender, Jones replied, 'I have not yet begun to fight.'","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Bonhomme%20Richard%2C%201779.%20Copy%20of%20artwork%20by%20F.%20Muller%2C%201883%20-%201966%20-%20NARA%20-%20512971.tif?width=1024"},{"name":"USS Alliance","rarity":"rare","id":"uss-alliance-1778","subtitle":"Sailing Frigate","details":"Launched in 1778, Alliance was the Continental Navy's crack frigate; in March 1783 she fought HMS Sybil in the Revolution's last naval battle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/NH%201336%20%2817166575515%29.jpg?width=1024"},{"name":"USS Ranger","rarity":"rare","id":"uss-ranger-1777","subtitle":"Sailing Sloop","details":"Launched in 1777, John Paul Jones's sloop Ranger won the first foreign salute to the American flag and raided Whitehaven on the English coast in 1778.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/First%20Recognition%20of%20the%20American%20Flag%20by%20a%20Foreign%20Government.jpg?width=1024"},{"name":"USS Wasp","rarity":"rare","id":"uss-wasp-1807","subtitle":"Sailing Sloop","details":"Launched in 1807, Wasp won a brilliant single-ship victory over HMS Frolic in October 1812, only to be captured by HMS Poictiers a few hours later.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Wasp%20capturing%20HMS%20Frolic.jpg?width=1024"},{"name":"USS Hornet","rarity":"rare","id":"uss-hornet-1805","subtitle":"Sailing Brig","details":"Launched in 1805, Hornet bombarded Tripoli, fought through the War of 1812, and sank HMS Penguin in a sharp 22-minute action in March 1815.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hornet%20and%20Penguin.jpg?width=1024"},{"name":"USS Peacock","rarity":"rare","id":"uss-peacock-1813","subtitle":"Sailing Sloop","details":"Launched in 1813, Peacock defeated HMS Epervier in 1814 and took the last prize of the War of 1812; she later joined the U.S. Exploring Expedition.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Peacock%20in%20ice%2C%201840.jpg?width=1024"},{"name":"USS Langley (CV-1)","rarity":"uncommon","id":"uss-langley-cv-1","subtitle":"Aircraft Carrier","details":"The Navy's first aircraft carrier, converted from the collier Jupiter and commissioned in 1922; she trained the first carrier pilots and was lost in 1942.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Langley_%28CV-1%29_underway_in_June_1927_%28cropped%29.jpg?width=1024"},{"name":"USS Ticonderoga (CV-14)","rarity":"uncommon","id":"uss-ticonderoga-cv-14","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in 1944 that fought at the Philippines and Okinawa, then recovered the Apollo 16 and Skylab 2 crews in the 1970s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Ticonderoga_%28CVA-14%29_refueling_from_USS_Ashtabula_%28AO-51%29_off_Vietnam_c1966.jpg?width=1024"},{"name":"USS Randolph (CV-15)","rarity":"uncommon","id":"uss-randolph-cv-15","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in 1944 that survived a kamikaze hit at Ulithi, served through the Cold War, and recovered astronaut Gus Grissom in 1961.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Randolph_%28CVS-15%29_underway_on_25_October_1959_%28USN_1059601%29.jpg?width=1024"},{"name":"USS Wasp (CV-18)","rarity":"uncommon","id":"uss-wasp-cv-18","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in 1943 and named for the lost CV-7; she later recovered Gemini astronauts in the 1960s and served until 1972.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Wasp_%28CVS-18%29_underway_at_sea%2C_circa_in_early_1967_%28NH_97509%29.jpg?width=1024"},{"name":"USS Bennington (CV-20)","rarity":"uncommon","id":"uss-bennington-cv-20","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in 1944 that fought in the Pacific, survived a fatal 1954 catapult explosion, and served on until 1970.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Bennington_%28CVS-20%29_underway_at_sea_on_5_March_1965_%28NH_97581%29.jpg?width=1024"},{"name":"USS Boxer (CV-21)","rarity":"uncommon","id":"uss-boxer-cv-21","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in April 1945; she became a Korean War workhorse and later an amphibious assault ship ferrying helicopters and troops.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Boxer_%28CV-21%29_underway%2C_circa_in_1948.jpg?width=1024"},{"name":"USS Bon Homme Richard (CV-31)","rarity":"uncommon","id":"uss-bon-homme-richard-cv-31","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in November 1944, nicknamed 'Bonnie Dick'; she fought in World War II's final year and again in Korea and Vietnam.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Bon_Homme_Richard_%28CVA-31%29_underway_at_sea_c1959.jpg?width=800"},{"name":"USS Leyte (CV-32)","rarity":"uncommon","id":"uss-leyte-cv-32","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in 1946 and named for the Battle of Leyte Gulf; a Korean War veteran later converted to an antisubmarine warfare carrier.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Leyte_%28CV-32%29_with_F9Fs.jpg?width=1024"},{"name":"USS Kearsarge (CV-33)","rarity":"uncommon","id":"uss-kearsarge-cv-33","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in 1946, named for the Civil War sloop that sank CSS Alabama; she recovered Mercury astronaut Wally Schirra in 1962.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Kearsarge_%28CVS-33%29_underway_at_sea_in_1966.jpg?width=1024"},{"name":"USS Oriskany (CV-34)","rarity":"uncommon","id":"uss-oriskany-cv-34","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in 1950, the 'Mighty O' of Vietnam fame; a 1966 flare fire took 44 crew, and she is now a diving reef off Florida.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Oriskany_%28CVA-34%29_near_Midway_Atoll_1967.jpg?width=1024"},{"name":"USS Lake Champlain (CV-39)","rarity":"uncommon","id":"uss-lake-champlain-cv-39","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in June 1945, too late for combat; in May 1961 she recovered Alan Shepard, the first American in space.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Lake_Champlain_%28CVS-39%29_underway_in_February_1965_%28USN_1114106%29.jpg?width=1024"},{"name":"USS Tarawa (CV-40)","rarity":"uncommon","id":"uss-tarawa-cv-40","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in December 1945 and named for the hard-fought 1943 Marine Corps battle in the Gilbert Islands; she served until 1960.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Tarawa_%28CVA-40%29_underway_at_sea_on_18_December_1952.jpg?width=1024"},{"name":"USS Franklin D. Roosevelt (CV-42)","rarity":"uncommon","id":"uss-franklin-d-roosevelt-cv-42","subtitle":"Aircraft Carrier","details":"Midway-class carrier commissioned in October 1945 and named for the president who had died in office that spring; she served in the Atlantic until 1977.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Franklin_D._Roosevelt_%28CVA-42%29_underway_in_1971_%28NNAM.1996.488.062.023%29.jpg?width=1024"},{"name":"USS Valley Forge (CV-45)","rarity":"uncommon","id":"uss-valley-forge-cv-45","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in 1946 that made an early round-the-world cruise and won eight battle stars launching Korean War air strikes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Valley_Forge_%28LPH-8%29_transporting_A-4_Skyhawks_c1965.jpg?width=1024"},{"name":"USS Philippine Sea (CV-47)","rarity":"uncommon","id":"uss-philippine-sea-cv-47","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in 1946 and named for the great 1944 carrier battle; she spent her career as an antisubmarine carrier until 1958.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Philippine_Sea_%28CVA-47%29_underway_at_sea_on_9_July_1955_%2880-G-K-18429%29.jpg?width=1024"},{"name":"USS Belleau Wood (CVL-24)","rarity":"uncommon","id":"uss-belleau-wood-cvl-24","subtitle":"Light Aircraft Carrier","details":"Independence-class light carrier commissioned in 1943, named for the World War I Marine battle; she later served France under the name Bois Belleau.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Belleau_Wood_%28CVL-24%29_underway_on_22_December_1943_%28NH_97269%29.jpg?width=1024"},{"name":"USS Bataan (CVL-29)","rarity":"uncommon","id":"uss-bataan-cvl-29","subtitle":"Light Aircraft Carrier","details":"Independence-class light carrier commissioned in 1943, named for the fallen Philippine peninsula; she returned to combat in Korea before retiring in 1954.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Bataan_%28CVL-29%29_underway_at_sea_in_January_1952.jpg?width=1024"},{"name":"USS New Mexico (BB-40)","rarity":"uncommon","id":"uss-new-mexico-bb-40","subtitle":"Battleship","details":"Lead ship of her class, commissioned in 1918; the first US battleship with a turbo-electric drive, she bombarded positions from Attu to Okinawa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_New_Mexico_BB-40_1921.jpg?width=1024"},{"name":"USS Mississippi (BB-41)","rarity":"uncommon","id":"uss-mississippi-bb-41","subtitle":"Battleship","details":"New Mexico-class battleship commissioned in 1917; she fought across the Pacific in World War II and later became a floating missile test platform.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Mississippi_%28BB-41%29_operating_at_sea_during_the_later_1930s.jpg?width=1024"},{"name":"USS Idaho (BB-42)","rarity":"uncommon","id":"uss-idaho-bb-42","subtitle":"Battleship","details":"New Mexico-class battleship commissioned in 1919; she patrolled the Atlantic early in World War II, then bombarded Iwo Jima and Okinawa in 1945.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Idaho_%28BB-42%29_at_1927_naval_review.jpg?width=1024"},{"name":"USS Delaware (BB-28)","rarity":"uncommon","id":"uss-delaware-bb-28","subtitle":"Battleship","details":"Lead ship of her class, commissioned in 1910; the second US dreadnought class, she escorted troop convoys across the Atlantic in World War I.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Delaware_%28BB28%29._Starboard_bow%2C_Guantanamo_Bay%2C_01-01-1920_-_NARA_-_512950.jpg?width=1024"},{"name":"USS North Dakota (BB-29)","rarity":"uncommon","id":"uss-north-dakota-bb-29","subtitle":"Battleship","details":"Delaware-class dreadnought commissioned in 1910; the first US battleship completed with steam turbines in place of triple-expansion engines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_North_Dakota_BB-29.jpg?width=1024"},{"name":"USS South Carolina (BB-26)","rarity":"uncommon","id":"uss-south-carolina-bb-26","subtitle":"Battleship","details":"Lead ship of the first US dreadnought class, commissioned in 1910; her superimposed turret arrangement became a hallmark of battleship design.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Uss_south_carolina_bb_%28cropped%29.jpg?width=1024"},{"name":"USS Michigan (BB-27)","rarity":"uncommon","id":"uss-michigan-bb-27","subtitle":"Battleship","details":"South Carolina-class dreadnought commissioned in 1910; she patrolled the Atlantic and escorted convoys during the First World War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Photograph_of_the_Battleship_USS_Michigan_-_NARA_-_19-N-13573.jpg?width=1024"},{"name":"USS Indiana (BB-1)","rarity":"uncommon","id":"uss-indiana-bb-1","subtitle":"Battleship","details":"Lead ship of the first US battleship class, commissioned in 1895; heavily armed for her size, she fought off Santiago de Cuba in the Spanish-American War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Indiana_LOC_npcc_32733.jpg?width=1024"},{"name":"USS Massachusetts (BB-2)","rarity":"uncommon","id":"uss-massachusetts-bb-2","subtitle":"Battleship","details":"Indiana-class battleship commissioned in 1896; she fought at Santiago de Cuba and later served as a coastal defense ship in the First World War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Massachusetts_%28BB2%29._Starboard_bow_at_wharf%2C_06-1901_-_NARA_-_535432.jpg?width=1024"},{"name":"USS Iowa (BB-4)","rarity":"uncommon","id":"uss-iowa-bb-4","subtitle":"Battleship","details":"Seagoing battleship commissioned in 1897, built for better speed and range than the Indiana class; she fought at Santiago de Cuba in 1898.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Iowa_-_NH_61211.jpg?width=1024"},{"name":"USS Kearsarge (BB-5)","rarity":"uncommon","id":"uss-kearsarge-bb-5","subtitle":"Battleship","details":"Lead ship of her class, commissioned in 1900; the only US battleship not named for a state, she later served for decades as a crane ship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kearsarge_%28BB5%29%2C_converted_to_craneship_in_1920._Port_bow%2C_at_wharf%2C_09-18-1899_-_NARA_-_535431.jpg?width=1024"},{"name":"USS Illinois (BB-7)","rarity":"uncommon","id":"uss-illinois-bb-7","subtitle":"Battleship","details":"Lead ship of her class, commissioned in 1901; she sailed around the world with the Great White Fleet in 1907-09 and later served New York's Naval Militia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Illinois_BB-7.jpg?width=1024"},{"name":"USS Maine (BB-10)","rarity":"uncommon","id":"uss-maine-bb-10","subtitle":"Battleship","details":"Lead ship of her class, commissioned in 1902; named for the battleship lost at Havana in 1898, she cruised with the Great White Fleet in 1907-09.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Maine_underway.tiff?width=1024"},{"name":"USS Northampton (CA-26)","rarity":"uncommon","id":"uss-northampton-ca-26","subtitle":"Heavy Cruiser","details":"Northampton-class heavy cruiser commissioned in 1930. She screened the carriers of the Doolittle Raid and was lost at Tassafaronga in 1942.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Northampton_%28CA-26%29_at_Brisbane_on_5_August_1941_%28NH_94596%29.jpg?width=1024"},{"name":"USS Minneapolis (CA-36)","rarity":"uncommon","id":"uss-minneapolis-ca-36","subtitle":"Heavy Cruiser","details":"New Orleans-class heavy cruiser commissioned in 1934. Her bow was torn off by a torpedo at Tassafaronga, yet she survived to earn 17 battle stars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Minneapolis_%28CA-36%29_at_Pearl_Harbor_Naval_Shipyard_on_11_April_1943_%2880-G-K-544%29.jpg?width=1024"},{"name":"USS St. Paul (CA-73)","rarity":"uncommon","id":"uss-st-paul-ca-73","subtitle":"Heavy Cruiser","details":"Baltimore-class heavy cruiser commissioned in 1945. In the Korean War she bombarded Wonsan, and she later fired in support of troops in Vietnam.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Saint_Paul_%28CA-73%29_off_Wonsan%2C_Korea%2C_20_April_1951_%2880-K-11868%29.jpg?width=1024"},{"name":"USS Pittsburgh (CA-72)","rarity":"uncommon","id":"uss-pittsburgh-ca-72","subtitle":"Heavy Cruiser","details":"Baltimore-class heavy cruiser commissioned in 1944. A typhoon tore away her bow in June 1945, yet she steamed to Guam under her own power.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Pittsburgh_%28CA-72%29_underway_on_11_October_1955_%28NH_98248%29.jpg?width=1024"},{"name":"USS Canberra (CA-70)","rarity":"uncommon","id":"uss-canberra-ca-70","subtitle":"Heavy Cruiser","details":"Baltimore-class heavy cruiser commissioned in 1943, named to honor the sunken Australian cruiser Canberra. She became missile cruiser CAG-2 in 1956.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Canberra_%28CAG-2%29_underway_at_sea_on_9_January_1961_%28KN-1526%29.jpg?width=1024"},{"name":"USS Omaha (CL-4)","rarity":"uncommon","id":"uss-omaha-cl-4","subtitle":"Light Cruiser","details":"Lead Omaha-class light cruiser, commissioned in 1923. In November 1941, weeks before Pearl Harbor, she boarded and captured a German blockade runner.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Omaha_%28CL-4%29_in_New_York_Harbor%2C_10_February_1943_%2819-N-40594%29.jpg?width=1024"},{"name":"USS Brooklyn (CL-40)","rarity":"uncommon","id":"uss-brooklyn-cl-40","subtitle":"Light Cruiser","details":"Lead Brooklyn-class light cruiser, commissioned in 1937 with fifteen 6-inch guns. She later served Chile as O'Higgins for four decades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Brooklyn_%28CL-40%29_in_the_Hudson_River%2C_in_1939_%2880-G-1023215%29.jpg?width=1024"},{"name":"USS Honolulu (CL-48)","rarity":"uncommon","id":"uss-honolulu-cl-48","subtitle":"Light Cruiser","details":"Brooklyn-class light cruiser commissioned in 1938. She fought from Pearl Harbor to Leyte Gulf and survived a torpedo hit at Kolombangara in 1943.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Honolulu_%28CL-48%29_underway_at_sea_on_9_February_1939_%28NH_53562%29.jpg?width=1024"},{"name":"USS St. Louis (CL-49)","rarity":"uncommon","id":"uss-st-louis-cl-49","subtitle":"Light Cruiser","details":"St. Louis-class light cruiser commissioned in 1939, nicknamed 'Lucky Lou.' She survived Pearl Harbor undamaged and earned 11 battle stars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_St._Louis_%28CL-49%29_off_San_Pedro%2C_California_%28USA%29%2C_on_5_October_1944_%2819-N-72219%29.jpg?width=1024"},{"name":"USS San Diego (CL-53)","rarity":"uncommon","id":"uss-san-diego-cl-53","subtitle":"Light Cruiser","details":"Atlanta-class light cruiser commissioned in 1942. She earned 18 battle stars and was among the first major Allied warships to enter Tokyo Bay in 1945.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_San_Diego_%28CL-53%29_underway_on_8_March_1944_%28NH_97825%29.jpg?width=1024"},{"name":"USS Cleveland (CL-55)","rarity":"uncommon","id":"uss-cleveland-cl-55","subtitle":"Light Cruiser","details":"Lead ship of the 27-strong Cleveland class, the most numerous US light cruiser class. Commissioned in 1942, she fought from Guadalcanal to Okinawa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Cleveland_%28CL-55%29_underway_at_sea_in_late_1942_%28NH_55173%29.jpg?width=1024"},{"name":"USS Santa Fe (CL-60)","rarity":"uncommon","id":"uss-santa-fe-cl-60","subtitle":"Light Cruiser","details":"Cleveland-class light cruiser commissioned in 1942. She famously stood by the burning carrier Franklin in March 1945, helping to save the ship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/19-N-40686_USS_Santa_Fe.jpg?width=1024"},{"name":"USS Bainbridge (CGN-25)","rarity":"uncommon","id":"uss-bainbridge-cgn-25","subtitle":"Guided Missile Cruiser","details":"Nuclear-powered missile cruiser commissioned in 1962. In 1964 she circled the globe without refueling alongside Enterprise and Long Beach.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Bainbridge_%28CGN-25%29_1986.jpg?width=1024"},{"name":"USS Benson (DD-421)","rarity":"uncommon","id":"uss-benson-dd-421","subtitle":"Destroyer","details":"Lead ship of the Benson class, commissioned in 1940; she escorted Atlantic convoys and supported the landings in Sicily, Italy and southern France.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Benson%20%28DD-421%29%20underway%20at%20sea%20c1944.jpg?width=1024"},{"name":"USS Gleaves (DD-423)","rarity":"uncommon","id":"uss-gleaves-dd-423","subtitle":"Destroyer","details":"Lead ship of the Gleaves class, commissioned in 1940; she supported the invasions of Sicily and southern France and Atlantic convoy operations.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Gleaves%20%28DD-423%29%20underway%20on%2018%20June%201941%20%28513043%29.jpg?width=1024"},{"name":"USS Buchanan (DD-484)","rarity":"uncommon","id":"uss-buchanan-dd-484","subtitle":"Destroyer","details":"Gleaves-class destroyer commissioned in 1942; among the war's hard-worked destroyers, she fought at Guadalcanal, Tarawa and the Philippines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Buchanan_%28DD-484%29_underway_at_sea%2C_circa_in_August_1942_%2880-G-K-417%29.jpg?width=1024"},{"name":"USS Duncan (DD-485)","rarity":"uncommon","id":"uss-duncan-dd-485","subtitle":"Destroyer","details":"Gleaves-class destroyer commissioned in 1942; lost in October 1942 at the Battle of Cape Esperance, the US Navy's first night victory of the war.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Duncan_%28DD-485%29_underway_in_the_South_Pacific_on_7_October_1942_%28NH_90495%29.jpg?width=1024"},{"name":"USS Strong (DD-467)","rarity":"uncommon","id":"uss-strong-dd-467","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; lost in July 1943 in the Kula Gulf after helping sink a Japanese destroyer the night she went down.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Strong_%28DD-467%29_underway_at_sea%2C_circa_in_early_July_1943_%2880-G-52931%29.jpg?width=1024"},{"name":"USS Chevalier (DD-451)","rarity":"uncommon","id":"uss-chevalier-dd-451","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; lost at the Battle of Vella Lavella in October 1943 after ramming the Japanese destroyer Yugumo.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Chevalier_%28DD-451%29_off_Boston%2C_Massachusetts_%28USA%29%2C_on_24_October_1942_%28NH_107952%29.jpg?width=1024"},{"name":"USS De Haven (DD-469)","rarity":"uncommon","id":"uss-de-haven-dd-469","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; sunk by Japanese dive bombers off Savo Island in February 1943 during the Guadalcanal campaign.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_De_Haven_%28DD-469%29_off_Savo_Island%2C_January_1943.jpg?width=1024"},{"name":"USS Charles Ausburne (DD-570)","rarity":"uncommon","id":"uss-charles-ausburne-dd-570","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; flagship of Captain Arleigh Burke's DesRon 23, the celebrated 'Little Beavers' of the Solomons.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Charles_Ausburne_%28DD-570%29_underway_at_sea_on_23_March_1944_%2880-G-232122%29.jpg?width=1024"},{"name":"USS Claxton (DD-571)","rarity":"uncommon","id":"uss-claxton-dd-571","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; one of Arleigh Burke's 'Little Beavers,' she fought through the Solomon Islands campaign.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Claxton_%28DD-571%29_off_the_Mare_Island_Naval_Shipyard_on_13_May_1944_%2819-N-66231%29.jpg?width=1024"},{"name":"USS Dyson (DD-572)","rarity":"uncommon","id":"uss-dyson-dd-572","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; a 'Little Beavers' ship, she later transferred to West Germany and served as Zerstörer 5.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Dyson%20%28DD-572%29%20underway%20off%20the%20Mare%20Island%20Naval%20Shipyard%2C%20California%20%28USA%29%2C%20on%2030%20September%201944%20%2819-N-73206%29.jpg?width=1024"},{"name":"USS Stanly (DD-478)","rarity":"uncommon","id":"uss-stanly-dd-478","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; in April 1945 off Okinawa she survived a Japanese Ohka rocket bomb that passed through her bow.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Stanly%20%28DD-478%29%20underway%20off%20Pearl%20Harbor%2C%20circa%20in%201943%20%2819-N-48591%29.jpg?width=1024"},{"name":"USS Heermann (DD-532)","rarity":"uncommon","id":"uss-heermann-dd-532","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; at the Battle off Samar she attacked Japanese battleships and cruisers and survived the fight.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Heermann%20%28DD-532%29%20underway%2C%20circa%20in%20the%20early%201950s%20%28NH%20107247%29.jpg?width=1024"},{"name":"USS Haggard (DD-555)","rarity":"uncommon","id":"uss-haggard-dd-555","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; badly damaged by a kamikaze off Okinawa in April 1945 while screening the battleship fleet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Haggard%20%28DD-555%29%20underway%20on%2022%20September%201943%20%2819-N-53909%29.jpg?width=1024"},{"name":"USS Hailey (DD-556)","rarity":"uncommon","id":"uss-hailey-dd-556","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; she screened carriers and convoys across the Pacific and later served Brazil as Pernambuco.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Hailey%20%28DD-556%29%20off%20Norfolk%2C%20Virginia%20%28USA%29%2C%20in%201960.jpg?width=1024"},{"name":"USS McDermut (DD-677)","rarity":"uncommon","id":"uss-mcdermut-dd-677","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; at Surigao Strait her torpedoes helped sink two Japanese destroyers in history's last battleship duel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_McDermut_%28DD-677%29_underway_at_sea_off_Quonset_Point%2C_Rhode_Island_%28USA%29%2C_circa_the_mid-1950s_%28NH_107191%29.jpg?width=1024"},{"name":"USS Ingraham (DD-444)","rarity":"uncommon","id":"uss-ingraham-dd-444","subtitle":"Destroyer","details":"Gleaves-class destroyer commissioned in 1942; she escorted Atlantic convoys and supported the Sicily, Salerno and southern France landings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Uss_Ingrahm.JPG?width=1024"},{"name":"USS Gridley (DD-380)","rarity":"uncommon","id":"uss-gridley-dd-380","subtitle":"Destroyer","details":"Lead ship of her class, commissioned in 1938; she screened carriers at Coral Sea and Midway and fought through the Guadalcanal campaign.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USSGridleyDD380.jpg?width=1024"},{"name":"USS Craven (DD-382)","rarity":"uncommon","id":"uss-craven-dd-382","subtitle":"Destroyer","details":"Gridley-class destroyer commissioned in 1937; she was at Pearl Harbor on 7 December 1941 and went on to escort carriers in the Pacific.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Craven_%28DD-382%29_underway_in_November_1943.jpg?width=1024"},{"name":"USS Maury (DD-401)","rarity":"uncommon","id":"uss-maury-dd-401","subtitle":"Destroyer","details":"Benham-class destroyer commissioned in 1938; she set a destroyer speed record on trials and later fought at the Battle of Vella Gulf.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Maury_%28DD-401%29_as_completed%2C_in_mid-1938_%28NH_42150%29.jpg?width=1024"},{"name":"USS Benham (DD-397)","rarity":"uncommon","id":"uss-benham-dd-397","subtitle":"Destroyer","details":"Lead ship of her class, commissioned in 1939; she rescued Yorktown survivors at Midway and was lost in the Naval Battle of Guadalcanal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Benham_%28DD-397%29_anchored_off_New_York_City_%28USA%29%2C_in_1939_%28NH_81173%29.jpg?width=1024"},{"name":"USS Forrest Sherman (DD-931)","rarity":"uncommon","id":"uss-forrest-sherman-dd-931","subtitle":"Destroyer","details":"Lead ship of the last all-gun American destroyer class, commissioned in 1955; she served through the Cold War and the Vietnam era.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Forrest_Sherman_%28DD-931%29_at_sea_c1978.jpg?width=1024"},{"name":"USS Barry (DD-933)","rarity":"uncommon","id":"uss-barry-dd-933","subtitle":"Destroyer","details":"Forrest Sherman-class destroyer commissioned in 1956; after Cold War service she spent decades as a display ship at the Washington Navy Yard.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Barry.jpg?width=1024"},{"name":"USS Charles F. Adams (DDG-2)","rarity":"uncommon","id":"uss-charles-f-adams-ddg-2","subtitle":"Guided Missile Destroyer","details":"Lead ship of her class of guided missile destroyers, commissioned in 1960; she joined the Mercury 8 recovery and Cuban Missile Crisis operations.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Charles_F._Adams_%28DDG-2%29_underway_at_high_speed_while_running_trials%2C_on_31_August_1960_%28NH_106724%29.jpg?width=1024"},{"name":"USS Fitzgerald (DDG-62)","rarity":"uncommon","id":"uss-fitzgerald-ddg-62","subtitle":"Guided Missile Destroyer","details":"Arleigh Burke-class destroyer commissioned in 1995; she is remembered for the seven sailors lost in a collision off Japan in June 2017.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US_Navy_050813-N-8492C-111_The_guided_missile_destroyer_USS_Fitzgerald_%28DDG_62%29_prepares_to_get_into_position_with_ships_of_the_Kitty_Hawk_Carrier_Strike_Group_during_a_formation_exercise.jpg?width=1024"},{"name":"USS John S. McCain (DDG-56)","rarity":"uncommon","id":"uss-john-s-mccain-ddg-56","subtitle":"Guided Missile Destroyer","details":"Arleigh Burke-class destroyer commissioned in 1994 and named for two admirals; ten of her sailors were lost in a 2017 collision at sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_John_S._McCain_DDG-56.jpg?width=1024"},{"name":"USS Cobia (SS-245)","rarity":"uncommon","id":"uss-cobia-ss-245","subtitle":"Submarine","details":"Commissioned in 1944, Cobia made six war patrols and is now preserved as a museum ship at Manitowoc, Wisconsin, a wartime submarine-building port.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USSCobiaSS245.jpg?width=1024"},{"name":"USS Croaker (SS-246)","rarity":"uncommon","id":"uss-croaker-ss-246","subtitle":"Submarine","details":"Commissioned in 1944, Croaker made six patrols, later served as a hunter-killer submarine, and is now a museum ship at Buffalo, New York.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Croaker%3B0824616.jpg?width=1024"},{"name":"USS Lionfish (SS-298)","rarity":"uncommon","id":"uss-lionfish-ss-298","subtitle":"Submarine","details":"Commissioned in 1944, Balao-class Lionfish made two war patrols and is now preserved as a museum ship at Battleship Cove in Fall River.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Lionfish_%28SS-298%29.jpg?width=1024"},{"name":"USS Becuna (SS-319)","rarity":"uncommon","id":"uss-becuna-ss-319","subtitle":"Submarine","details":"Commissioned in 1944, Becuna made five patrols in the Pacific and is now a museum ship alongside the cruiser Olympia in Philadelphia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Becuna%3B0831914.jpg?width=1024"},{"name":"USS Pampanito (SS-383)","rarity":"uncommon","id":"uss-pampanito-ss-383","subtitle":"Submarine","details":"Commissioned in 1943, Pampanito rescued 73 British and Australian POW survivors at sea and is now a museum ship at San Francisco's Pier 45.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pampanito_%28submarine%2C_San_Francisco%29.JPG?width=1024"},{"name":"USS Ling (SS-297)","rarity":"uncommon","id":"uss-ling-ss-297","subtitle":"Submarine","details":"Commissioned in 1945, Balao-class Ling made one war patrol before the surrender and was long preserved as a museum ship at Hackensack, New Jersey.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USSLing1975.jpg?width=1024"},{"name":"USS Torsk (SS-423)","rarity":"uncommon","id":"uss-torsk-ss-423","subtitle":"Submarine","details":"Commissioned in 1944, Tench-class Torsk sank the last enemy vessels credited to U.S. forces in World War II and is a Baltimore museum ship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_TORSK_%28submarine%29_taken_from_walking_bridge.JPG?width=1024"},{"name":"USS Requin (SS-481)","rarity":"uncommon","id":"uss-requin-ss-481","subtitle":"Submarine","details":"Commissioned in 1945, Tench-class Requin later became the Navy's first fleet radar-picket submarine and is now a museum ship in Pittsburgh.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USSRequin.jpg?width=1024"},{"name":"USS Nautilus (SS-168)","rarity":"uncommon","id":"uss-nautilus-ss-168","subtitle":"Submarine","details":"Commissioned in 1930, the big V-boat Nautilus fought at Midway and landed Marine Raiders on Makin Atoll in August 1942, her first famous mission.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Nautilus_%28SS-168%29.jpg?width=1024"},{"name":"USS Narwhal (SS-167)","rarity":"uncommon","id":"uss-narwhal-ss-167","subtitle":"Submarine","details":"Commissioned in 1930, Narwhal was among the largest U.S. submarines of her day and carried troops and supplies on daring missions to enemy shores.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USSNarwhalSS167.jpg?width=1024"},{"name":"USS Argonaut (SS-166)","rarity":"uncommon","id":"uss-argonaut-ss-166","subtitle":"Submarine","details":"Commissioned in 1928, Argonaut was the largest U.S. submarine of her era and a minelayer lost with all hands off Rabaul in January 1943.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USSArgonautSS166.jpg?width=1024"},{"name":"USS Holland (SS-1)","rarity":"uncommon","id":"uss-holland-ss-1","subtitle":"Submarine","details":"Commissioned in 1900, Holland was the U.S. Navy's first submarine, John P. Holland's pioneering design that launched the American submarine force.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USs_Holland_SS-1_80-G-703837.jpg?width=1024"},{"name":"USS Parche (SSN-683)","rarity":"uncommon","id":"uss-parche-ssn-683","subtitle":"Attack Submarine","details":"Commissioned in 1974, Sturgeon-class Parche became the most decorated vessel in U.S. Navy history, earning nine Presidential Unit Citations.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Parche_%28SSN-683%29_off_Pearl_Harbor.jpg?width=1024"},{"name":"USS Narwhal (SSN-671)","rarity":"uncommon","id":"uss-narwhal-ssn-671","subtitle":"Attack Submarine","details":"Commissioned in 1969, Narwhal was a unique one-off submarine built to test a quieter power plant arrangement, serving with distinction for 30 years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Narwhal_SSN-671.jpg?width=1024"},{"name":"USS Jimmy Carter (SSN-23)","rarity":"uncommon","id":"uss-jimmy-carter-ssn-23","subtitle":"Attack Submarine","details":"Commissioned in 2005 and named for the only U.S. president to serve as a submariner, Jimmy Carter is the third and last of the Seawolf class.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Jimmy_Carter_SSN_23.jpg?width=1024"},{"name":"USS Halibut (SSGN-587)","rarity":"uncommon","id":"uss-halibut-ssgn-587","subtitle":"Guided Missile Submarine","details":"Commissioned in 1960, Halibut was the first submarine built to launch Regulus cruise missiles and later served in famous special missions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Halibut_SSGN-587.jpg?width=1024"},{"name":"USS Grayback (SSG-574)","rarity":"uncommon","id":"uss-grayback-ssg-574","subtitle":"Guided Missile Submarine","details":"Commissioned in 1958, Grayback was a Regulus missile submarine later converted to carry special warfare teams, serving until decommissioned in 1984.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Grayback%3B0857404.jpg?width=1024"},{"name":"USS Daniel Boone (SSBN-629)","rarity":"uncommon","id":"uss-daniel-boone-ssbn-629","subtitle":"Ballistic Missile Submarine","details":"Commissioned in 1964, Lafayette-class Daniel Boone made deterrent patrols from Atlantic and Pacific bases through the heart of the Cold War era.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Daniel_Boone_SSBN-629.jpg?width=1024"},{"name":"USS James Madison (SSBN-627)","rarity":"uncommon","id":"uss-james-madison-ssbn-627","subtitle":"Ballistic Missile Submarine","details":"Lead ship of her subclass, commissioned in 1964, James Madison carried Polaris and later Poseidon missiles on Cold War deterrent patrols at sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_James_Madison_SSBN-627.jpg?width=1024"},{"name":"USS Benjamin Franklin (SSBN-640)","rarity":"uncommon","id":"uss-benjamin-franklin-ssbn-640","subtitle":"Ballistic Missile Submarine","details":"Lead ship commissioned in 1965, Benjamin Franklin named the final subclass of the '41 for Freedom' ballistic missile submarine fleet of the 1960s.","image":"assets/sets/us-navy/images/uss-benjamin-franklin-ssbn-640.webp"},{"name":"USS Maryland (SSBN-738)","rarity":"uncommon","id":"uss-maryland-ssbn-738","subtitle":"Ballistic Missile Submarine","details":"Commissioned in 1992, Ohio-class Maryland was the thirteenth Trident boat, joining the Atlantic deterrent fleet based at Kings Bay, Georgia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flickr_-_Official_U.S._Navy_Imagery_-_USS_Maryland_transits_the_Saint_Marys_River..jpg?width=1024"},{"name":"USS Dolphin (AGSS-555)","rarity":"uncommon","id":"uss-dolphin-agss-555","subtitle":"Research Submarine","details":"Commissioned in 1968, research submarine Dolphin set deep-diving records for an operational boat and supported Navy science for nearly forty years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Dolphin_AGSS-555.jpg?width=1024"},{"name":"USS Saipan (LHA-2)","rarity":"uncommon","id":"uss-saipan-lha-2","subtitle":"Amphibious Assault Ship","details":"Commissioned in 1977, Saipan was an early US carrier-type ship with women permanently in her crew, serving Marine landings for three decades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Saipan_LHA-2_amphibious_assault_ship.jpg?width=1024"},{"name":"USS Belleau Wood (LHA-3)","rarity":"uncommon","id":"uss-belleau-wood-lha-3","subtitle":"Amphibious Assault Ship","details":"Commissioned in 1978, Belleau Wood carried Marines and Harriers worldwide, then ended her days as a target in a 2006 sinking exercise at sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US_Navy_050711-N-7286M-083_The_amphibious_assault_ship_USS_Belleau_Wood_%28LHA_3%29_Sailors_%22man_the_rails%22_for_the_final_time_as_they_sail_through_San_Diego_Harbor_completing_her_final_voyage_after_27_years_of_service.jpg?width=1024"},{"name":"USS Nassau (LHA-4)","rarity":"uncommon","id":"uss-nassau-lha-4","subtitle":"Amphibious Assault Ship","details":"Commissioned in 1979, Nassau spent 31 years putting Marines ashore, from Harrier flight decks in the Mediterranean to hurricane relief piers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US_Navy_040728-N-4459K-004_Crew_members_aboard_the_amphibious_assault_ship_USS_Nassau_%28LHA_4%29_create_formation_lettering_on_the_flight_deck_spelling_out.jpg?width=1024"},{"name":"USS Peleliu (LHA-5)","rarity":"uncommon","id":"uss-peleliu-lha-5","subtitle":"Amphibious Assault Ship","details":"Commissioned in 1980 and named for a savage 1944 island battle, Peleliu spent 35 years carrying Marines, Harriers and helicopters in the Pacific.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Peleliu%20%28LHA-5%29%20underway%20in%20August%202014.JPG?width=1024"},{"name":"USS Makin Island (LHD-8)","rarity":"uncommon","id":"uss-makin-island-lhd-8","subtitle":"Amphibious Assault Ship","details":"Commissioned in 2009, the last Wasp-class ship swapped gas turbines for hybrid electric drive, honoring the Marines' bold 1942 raid on Makin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amphibious_assault_ship_USS_Makin_Island_%28LHD_8%29_%28cropped%29.jpg?width=1024"},{"name":"USS Tripoli (LHA-7)","rarity":"uncommon","id":"uss-tripoli-lha-7","subtitle":"Amphibious Assault Ship","details":"Commissioned in 2020, Tripoli is an America-class big deck built around aviation, trialed as a 'lightning carrier' crowded with F-35B jets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Tripoli_%28LHA-7%29_underway_in_the_Gulf_of_Mexico_on_15_July_2019_%28190715-O-N0101-115%29.JPG?width=1024"},{"name":"USS New York (LPD-21)","rarity":"uncommon","id":"uss-new-york-lpd-21","subtitle":"Amphibious Transport Dock","details":"Commissioned in 2009, New York was built with seven and a half tons of steel salvaged from the World Trade Center worked into her bow stem.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_New_York_in_the_Hudson_River_200911.jpg?width=1024"},{"name":"USS Somerset (LPD-25)","rarity":"uncommon","id":"uss-somerset-lpd-25","subtitle":"Amphibious Transport Dock","details":"Commissioned in 2014, Somerset honors Somerset County, Pennsylvania, where Flight 93 came down on 9/11; steel from the site is worked into her.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_amphibious_transport_dock_ship_USS_Somerset_%28LPD_25%29_arrives_at_its_new_homeport_at_Naval_Base_San_Diego_%2813969753071%29.jpg?width=1024"},{"name":"USS Arlington (LPD-24)","rarity":"uncommon","id":"uss-arlington-lpd-24","subtitle":"Amphibious Transport Dock","details":"Commissioned in 2013, Arlington honors the Pentagon and the 184 people lost there on 9/11, with steel recovered from the building in her structure.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Arlington_%28LPD-24%29_underway_in_August_2014.JPG?width=1024"},{"name":"USS Denver (LPD-9)","rarity":"uncommon","id":"uss-denver-lpd-9","subtitle":"Amphibious Transport Dock","details":"Commissioned in 1968, Austin-class Denver spent 46 years carrying Marines and landing craft, among the oldest active ships when she retired.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US%20Navy%20100908-N-2218S-057%20USS%20Denver%20%28LPD%209%29%20and%20embarked%20Marines%20are%20underway%20in%20the%20western%20Pacific%20Ocean.jpg?width=1024"},{"name":"USS Philadelphia","rarity":"uncommon","id":"uss-philadelphia-1776","subtitle":"Gunboat","details":"A Lake Champlain gunboat built in 1776, Philadelphia fought at Valcour Island and sank; raised in 1935, she is exhibited by the Smithsonian.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/GunboatPhiladelphia.jpg?width=1024"},{"name":"USS Providence","rarity":"uncommon","id":"uss-providence-1775","subtitle":"Sailing Sloop","details":"John Paul Jones's first command, the sloop Providence took a dozen prizes on one bold 1776 cruise and outran the British frigate Solebay.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Continental%20Sloop%20Providence%20%281775-1779%29.jpg?width=1024"},{"name":"USS Andrew Doria","rarity":"uncommon","id":"uss-andrew-doria-1775","subtitle":"Sailing Brig","details":"A brig bought in 1775, Andrew Doria received the 'First Salute' to the American flag, fired by Dutch Fort Oranje on St. Eustatius in November 1776.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Andrew%20Doria%20NH%2085510-KN.jpg?width=1024"}]});
